<template><section class="revision-comparison"><label>对比基准<AppSelect v-model="baseId"><AppSelectOption value="">选择另一份快照</AppSelectOption><AppSelectOption v-for="row in versions.filter(r=>r.revisionId!==selected?.revisionId)" :key="row.revisionId" :value="row.revisionId">V{{ row.version }} · {{ row.createdAt?.slice(0,16).replace('T',' ') }}</AppSelectOption></AppSelect></label><p v-if="error" role="alert">{{ error }}</p><p v-else-if="loading">正在比较…</p><template v-else-if="baseline && selected"><p class="diff-note">绿色为新增，红色为删除；正文按纯文本比较，图片和排版请结合原预览查看。</p><div v-for="field in fields" :key="field.key"><h3>{{ field.label }}</h3><pre class="diff-lines"><span v-for="(line,index) in changes(field.key)" :key="index" :class="line.kind">{{ line.kind==='add'?'+ ':line.kind==='remove'?'− ':'  ' }}{{ line.text }}{{ '\n' }}</span></pre></div></template></section></template>
<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue'
import request from '@/utils/request'
import {compareLines} from '@/utils/revisionDiff'
import {latestRequest} from '@/utils/latestRequest'
const props=defineProps<{articleId:string;selected:any;versions:any[]}>()
const fields=[{key:'title',label:'标题'},{key:'summary',label:'摘要'},{key:'content',label:'正文'}],baseId=ref(''),baseline=ref<any>(),loading=ref(false),error=ref(''),gate=latestRequest()
function text(value:any,key:string){const source=String(value?.payload?.[key]||'');if(key!=='content' || value?.payload?.contentType===2)return source;const doc=new DOMParser().parseFromString(source,'text/html');doc.querySelectorAll('script,style').forEach(e=>e.remove());doc.querySelectorAll('p,div,li,h1,h2,h3,h4,pre,tr,blockquote,br').forEach(e=>e.append('\n'));return doc.body.textContent?.trim()||''}
function changes(key:string){return compareLines(text(baseline.value,key),text(props.selected,key))}
watch(()=>[baseId.value,props.selected?.revisionId],async()=>{const run=gate.begin();baseline.value=undefined;error.value='';if(!baseId.value || baseId.value===props.selected?.revisionId){loading.value=false;return}loading.value=true;try{const r:any=await request.get(`/article/${props.articleId}/revisions/${baseId.value}`,{signal:run.signal});if(run.isCurrent())baseline.value=r.data}catch(e){if(run.isCurrent())error.value=e instanceof Error?e.message:'对比失败'}finally{if(run.isCurrent())loading.value=false}})
onUnmounted(()=>gate.cancel())
</script>
<style scoped>.revision-comparison{border-top:1px solid var(--ej-line);margin-top:24px;padding-top:16px}.revision-comparison select{margin-left:12px;max-width:100%;border:1px solid var(--ej-line);padding:8px;border-radius:10px;background:var(--ej-surface)}.diff-note{font-size:12px;color:var(--ej-muted)}.diff-lines{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto;border:1px solid var(--ej-line);padding:12px;border-radius:12px;font:13px/1.8 ui-monospace,monospace}.diff-lines span{display:inline}.add{background:#daf0bd;color:#245b2e}.remove{background:#ffe1d8;color:#963e30}.same{color:var(--ej-muted)}</style>
